import numpy as np,sys
from PIL import Image
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();cam='randomized_zed2_analogue_2';im=np.array(Image.open('/app/output/init_'+cam+'.png'));d=np.load('/app/output/init_'+cam+'_depth.npy');E=np.array(r.spec()['cameras'][cam]['mount']['extrinsic_cv']);Ei=np.linalg.inv(np.vstack([E,[0,0,0,1]]));K=np.array(r.spec()['cameras'][cam]['intrinsic_cv']);P=[];UV=[]
for v in range(180,245):
 for u in range(275,355):
  rgb=im[v,u];z=float(d[v,u]);
  if z<=0 or max(rgb)-min(rgb)>4 or not(35<rgb[0]<195):continue
  pc=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]);p=(Ei@pc)[:3]
  if 5.22<p[0]<5.38 and .19<p[1]<.31 and .965<p[2]<1.01:P.append(p);UV.append([u,v,rgb[0]])
P=np.array(P);UV=np.array(UV);print('n',len(P));print('bounds xyz',P.min(0),P.max(0));print('uv bounds',UV.min(0),UV.max(0));
xy=P[:,:2];m=xy.mean(0);C=np.cov((xy-m).T);ev,V=np.linalg.eigh(C);ix=np.argsort(ev)[::-1];ev=ev[ix];V=V[:,ix];print('mean',m,'eigenvalues',ev,'axes',V)
pr=(xy-m)@V;print('pca extent',pr.min(0),pr.max(0));
for q in np.quantile(pr,[.01,.05,.5,.95,.99],axis=0):print(q)
